import math
last=0.0
def control(obs):
 global last
 h=math.radians(obs['hitch_deg'])
 cam=obs.get('views',{}).get('camera')
 goal=last
 if cam:
  sides=[[],[]]
  for b,d in cam.get('walls',[]):
   a=math.radians(b)+h
   u=-d*math.cos(a); y=d*math.sin(a)
   if u>0.3 and abs(y)>0.35:
    sides[0 if y>0 else 1].append((u,y))
  for s in sides:s.sort()
  def interp(s,u):
   if not s:return None
   if u<s[0][0] or u>s[-1][0]:return None
   for i in range(1,len(s)):
    if s[i][0]>=u:
     a,b=s[i-1],s[i]
     return a[1]+(b[1]-a[1])*(u-a[0])/max(.001,b[0]-a[0])
  for u in [4.5,4,3.5,3,2.5,2]:
   l=interp(sides[0],u);r=interp(sides[1],u)
   if l is not None and r is not None:
    y=(l+r)/2
    goal=math.degrees(math.atan(2*2.6*y/(u*u+y*y)))
    break
  last=.75*last+.25*goal
 desired=max(-29,min(29,last))
 feed=math.degrees(math.atan(2.75*math.sin(math.radians(desired))/(2.6+1.05*math.cos(math.radians(desired)))))
 steer=feed+2.0*(obs['hitch_deg']-desired)
 return (max(-34,min(34,steer)),-0.7,-23)

