import math
last=0
def control(o):
 global last
 h=o['hitch_deg']; rear=o['rig']['trailer_rear']; pts=[]
 for name,v in o['views'].items():
  if name!='left_mirror': continue
  ox,oy=v['origin']
  for b,d in v['walls']:
   a=math.radians(b); x=ox+d*math.cos(a); y=oy+d*math.sin(a)
   if rear[0]-7<x<rear[0]+2 and y>0: pts.append((x,y))
 desired=0
 if len(pts)>3:
  mx=sum(p[0] for p in pts)/len(pts); my=sum(p[1] for p in pts)/len(pts)
  slope=sum((x-mx)*(y-my) for x,y in pts)/max(.01,sum((x-mx)**2 for x,y in pts))
  tx=rear[0]-3.5
  cy=my+slope*(tx-mx)-2.6*math.sqrt(1+slope*slope)
  desired=max(-25,min(25,math.degrees(math.atan2(cy-rear[1],3.5))))
 if o['t']-last>4:
  last=o['t']; print('lane',len(pts),'desired',round(desired,1),'hitch',round(h,1))
 return (max(-40,min(40,2*h-1.5*desired)),-0.6,64)

