import math
last=0.0
def interp(a,s):
 a=sorted(a)
 for (x,y),(xx,yy) in zip(a,a[1:]):
  if x<=s<=xx and xx>x: return y+(yy-y)*(s-x)/(xx-x)
 return None
def control(o):
 global last
 h=o['hitch_deg']; th=math.radians(-h); rear=o['rig']['trailer_rear']; sides=[[],[]]
 cam=o['views'].get('camera')
 if cam:
  for b,d in cam['walls']:
   b=math.radians(b); dx=cam['origin'][0]+d*math.cos(b)-rear[0]; dy=cam['origin'][1]+d*math.sin(b)-rear[1]
   s=-dx*math.cos(th)-dy*math.sin(th); l=-dx*math.sin(th)+dy*math.cos(th)
   if s>0 and abs(l)>1: sides[l>0].append((s,l))
  candidates=[]
  for s in [6,7,8,9,10,11]:
   a=interp(sides[0],s); b=interp(sides[1],s)
   if a is not None and b is not None: candidates.append((s,(a+b)/2))
  if candidates:
   s,l=min(candidates,key=lambda p:abs(p[0]-9))
   last=max(-38,min(38,math.degrees(math.asin(max(-0.62,min(0.62,20.4*l/(s*s+l*l)))))))
 steer=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))+1.8*(h-last)
 speed=-1.2 if abs(h)<20 else -0.8
 return (max(-42,min(42,steer)),speed,-41)

